void update(User user, int expectedVersion) {
  try (PreparedStatement stmt = conn.prepareStatement("UPDATE users SET email=?, version=version+1 WHERE id=? AND version=?")) {
    stmt.setString(1, user.email()); stmt.setLong(2, user.id()); stmt.setInt(3, expectedVersion);
    int rows = stmt.executeUpdate();
    if (rows == 0) throw new OptimisticLockException("Konflikt wersji dla id " + user.id());
  } catch (SQLException e) { throw new RuntimeException(e); }
}

long countByDepartment(String dept) {
  try (PreparedStatement stmt = conn.prepareStatement("SELECT COUNT(*) FROM users WHERE department=?")) {
    stmt.setString(1, dept);
    try (ResultSet rs = stmt.executeQuery()) { rs.next(); return rs.getLong(1); }
  } catch (SQLException e) { throw new RuntimeException(e); }
}
